def parse_url_parts(url):
    if url.startswith('http://') or url.startswith('https://'):
        scheme, rest = url.split('://', 1)
    else:
        scheme = ''
        rest = url
    if '/' in rest:
        host_part, rest = rest.split('/', 1)
        host = host_part
        if '?' in rest:
            path, query = rest.split('?', 1)
        else:
            path = rest
            query = ''
    else:
        host = rest
        path = ''
        query = ''
    return {'scheme': scheme, 'host': host, 'path': path, 'query': query}
