def parse_url_parts(url):
    result = {'scheme': '', 'host': '', 'path': '', 'query': ''}
    if '://' in url:
        scheme, rest = url.split('://', 1)
        result['scheme'] = scheme
        if '/' in rest:
            host_part, path_part = rest.split('/', 1)
            result['host'] = host_part
            if '?' in path_part:
                path_part, query_part = path_part.split('?', 1)
                result['path'] = '/' + path_part
                result['query'] = query_part
            else:
                result['path'] = '/' + path_part
        else:
            result['host'] = rest
    else:
        result['host'] = url
    return result
