                facing = "N"
        elif c == "F":
            if facing == "N":
                y += 1
            elif facing == "S":
                y -= 1
            elif facing == "E":
                x += 1
            elif facing == "W":
                x -= 1
            if (x, y) not in obstacles:
                cleaned.add((x, y))
    return len(cleaned)
