            if direction == "N":
                direction = "E"
            elif direction == "E":
                direction = "S"
            elif direction == "S":
                direction = "W"
            elif direction == "W":
                direction = "N"
        elif cmd == "F":
            if direction == "N":
                ny = y + 1
                nx = x
            elif direction == "S":
                ny = y - 1
                nx = x
            elif direction == "E":
                nx = x + 1
                ny = y
            elif direction == "W":
                nx = x - 1
                ny = y
            if (nx, ny) not in obstacles_set:
                x, y = nx, ny
                cleaned.add((x, y))
